// n8n Code node in "Run Once for Each Item" mode. Monetary math uses integer microdollars.
const { project, budgetUsd, usdPerSecond, shots } = $json;
const issues = [];
const rows = [];
const seen = new Set();

function microdollars(value) {
  if (typeof value !== 'number' || !Number.isFinite(value) || value < 0) return null;
  const match = /^(\d+)(?:\.(\d{1,6}))?$/.exec(String(value));
  if (!match) return null;
  const units = Number(match[1]) * 1000000 + Number((match[2] || '').padEnd(6, '0'));
  return Number.isSafeInteger(units) ? units : null;
}

const cap = microdollars(budgetUsd);
if (typeof project !== 'string' || !project.trim()) issues.push('Enter a project or batch name.');
if (cap === null) issues.push('Enter a non-negative numeric USD budget with at most six decimal places.');
if (!Array.isArray(shots) || !shots.length) issues.push('Add at least one shot.');
const rates = new Map();
for (const preset of ['768P', '2K']) {
  const rate = microdollars(usdPerSecond?.[preset]);
  if (rate !== null && rate > 0) rates.set(preset, rate);
}

let firstPass = 0;
let fullBatch = 0;
for (const [i, shot] of (Array.isArray(shots) ? shots : []).entries()) {
  const label = 'Row ' + (i + 1);
  const id = typeof shot?.shotId === 'string' ? shot.shotId.trim() : '';
  const preset = typeof shot?.preset === 'string' ? shot.preset.trim().toUpperCase() : '';
  const rate = rates.get(preset);
  const seconds = shot?.seconds;
  const takes = shot?.maxTakes;
  const before = issues.length;
  if (!id) issues.push(label + ': enter a shot ID.');
  else if (seen.has(id.toUpperCase())) issues.push(label + ': duplicate shot ID ' + id + '.');
  if (id) seen.add(id.toUpperCase());
  if (!rate) issues.push(label + ': use 768P or 2K and set a positive USD rate for it.');
  if (!Number.isInteger(seconds) || seconds < 4 || seconds > 15) issues.push(label + ': seconds must be an integer from 4 to 15.');
  if (!Number.isSafeInteger(takes) || takes < 1) issues.push(label + ': maxTakes must count the first take and be a positive integer.');
  if (issues.length !== before) continue;
  const one = rate * seconds;
  const all = one * takes;
  if (!Number.isSafeInteger(firstPass + one) || !Number.isSafeInteger(fullBatch + all)) {
    issues.push(label + ': the amount is too large to calculate precisely.');
    continue;
  }
  firstPass += one;
  fullBatch += all;
  rows.push({project, shotId:id, preset, seconds, maxTakes:takes, firstTakeUsd:one/1000000, estimatedMaxUsd:all/1000000});
}
if (issues.length) return {json:{project, status:'invalid_input', issues}};
return {json:{
  project, status: fullBatch <= cap ? 'within_budget' : 'over_budget',
  shotCount:rows.length, budgetUsd, firstPassUsd:firstPass/1000000,
  retakeAllowanceUsd:(fullBatch-firstPass)/1000000, estimatedMaxUsd:fullBatch/1000000,
  remainingUsd:(cap-fullBatch)/1000000, shots:rows
}};

const plan = $input.first().json;
if (!Array.isArray(plan.shots)) throw new Error((plan.issues || ['Invalid shot list.']).join(' '));
const config = $('Enter shot list, rates and cap').first().json;
const seen = new Set();
const records = [];
for (const [i, shot] of plan.shots.entries()) {
  const receipts = config.shots[i].receipts ?? [];
  if (!Array.isArray(receipts)) throw new Error(shot.shotId + ': receipts must be an array.');
  const entry = {shotId:shot.shotId, plannedPreset:shot.preset, plannedSeconds:shot.seconds, maxTakes:shot.maxTakes, shotCeilingUsd:shot.estimatedMaxUsd};
  if (!receipts.length) {
    records.push({json:{...entry, taskId:'', status:'no_receipt', note:'No task ID supplied.'}});
  }
  for (const receipt of receipts) {
    const id = receipt?.taskId;
    if (typeof id !== 'string' || !/^[a-zA-Z0-9_-]+$/.test(id)) throw new Error(shot.shotId + ': paste the exact task ID as a quoted string.');
    if (seen.has(id)) throw new Error('Duplicate task ID: ' + id + '. A receipt can belong to only one take.');
    seen.add(id);
    const charge = receipt.chargedUsd ?? null;
    if (charge !== null && (typeof charge !== 'number' || !Number.isFinite(charge) || charge < 0 || !Number.isSafeInteger(Math.round(charge * 1e6)) || Math.abs(Math.round(charge * 1e6) / 1e6 - charge) > 1e-12)) throw new Error(shot.shotId + ': chargedUsd must be null or a non-negative USD ledger amount with up to six decimal places.');
    records.push({json:{...entry, taskId:id, chargedUsd:charge, receiptsAbovePlan:receipts.length>shot.maxTakes}});
  }
}
return records;

const original = $('Is a task ID present?').item.json;
const response = $json;
const row = {...original, status:'lookup_error', actualPreset:'', outputSeconds:null, estimatedUsageUsd:null, note:''};
const done = note => ({json:{...row,note}});
if (response.statusCode !== 200) return done(response.statusCode ? 'HTTP ' + response.statusCode + '. Check the token, task age or service status.' : 'Network error. Run again with the same task ID.');
const t = response.body?.task;
if (!t || typeof t.id !== 'string' || t.id !== original.taskId) return done('Unmatched task ID in the response.');
row.status = typeof t.status === 'string' && t.status ? t.status : 'unknown_status';
if (row.status !== 'succeeded') return done('No completed usage estimate. Check the ledger for any posted charge.');
if (t.model !== 'MiniMax-H3' || (t.task_type && t.task_type !== 'generation')) return done('Different model or task type. Check this take against its own rate.');
row.actualPreset = String(t.resolution || '').toUpperCase();
const usage = t.usage;
if (typeof usage?.output_seconds !== 'number' || !Number.isFinite(usage.output_seconds) || usage.output_seconds <= 0) return done('Receipt has no positive output_seconds. Check usage in the ledger.');
row.outputSeconds = usage.output_seconds;
if (![usage.input_seconds,usage.input_image_count,usage.input_audio_seconds].every(v=>v===0)) return done('Reference inputs are present or unspecified. A text-only estimate would be incomplete.');
const rate = $('Enter shot list, rates and cap').first().json.usdPerSecond[row.actualPreset];
if (!['768P','2K'].includes(row.actualPreset) || typeof rate !== 'number' || !(rate > 0)) return done('No price for the returned resolution.');
const micros = Math.round(rate * row.outputSeconds * 1e6);
if (!Number.isSafeInteger(micros)) return done('Estimate exceeds supported numeric precision.');
row.estimatedUsageUsd = micros / 1e6;
const notes = [];
if (row.actualPreset !== row.plannedPreset) notes.push('Resolution differs from plan.');
if (row.outputSeconds !== row.plannedSeconds) notes.push('Output seconds differ from plan.');
if (row.receiptsAbovePlan) notes.push('More takes than planned.');
return done(notes.join(' '));

const plan = $('Price first takes and retakes').first().json;
const rows = $input.all().map(item=>item.json);
const tasks = rows.filter(row=>row.taskId);
const sum = (field) => {
  let total = 0;
  for (const row of tasks) {
    if (row[field] == null) continue;
    total += Math.round(row[field]*1e6);
    if (!Number.isSafeInteger(total)) throw new Error('Total exceeds supported numeric precision.');
  }
  return total/1e6;
};
const summary = {
  rowType:'project', project:plan.project, planStatus:plan.status,
  budgetUsd:plan.budgetUsd, plannedMaxUsd:plan.estimatedMaxUsd,
  plannedFirstPassUsd:plan.firstPassUsd, plannedRetakesUsd:plan.retakeAllowanceUsd,
  budgetLessPlanUsd:plan.remainingUsd, receiptCount:tasks.length,
  missingLedgerCharges:tasks.filter(r=>r.chargedUsd==null).length,
  receiptsWithoutEstimate:tasks.filter(r=>r.estimatedUsageUsd==null).length,
  recordedChargesSubtotalUsd:sum('chargedUsd'), pricedUsageSubtotalUsd:sum('estimatedUsageUsd'),
  note:'Subtotals cover known values only. Blank costs are unknown. Compare each receipt with the billing ledger.'
};
const byShot = new Map(plan.shots.map(s=>[s.shotId,[]]));
for (const row of rows) byShot.get(row.shotId).push(row);
const report = [{json:summary}];
for (const s of plan.shots) {
  const takes = byShot.get(s.shotId);
  const tracked = takes.filter(r=>r.taskId);
  report.push({json:{rowType:'shot plan',project:plan.project,shotId:s.shotId,plannedPreset:s.preset,plannedSeconds:s.seconds,maxTakes:s.maxTakes,shotCeilingUsd:s.estimatedMaxUsd,receiptCount:tracked.length,note:!tracked.length?'No task IDs supplied.':tracked.length>s.maxTakes?'More takes than planned.':''}});
  for (const t of tracked) {
    const variance = t.chargedUsd!=null && t.estimatedUsageUsd!=null ? (Math.round(t.chargedUsd*1e6)-Math.round(t.estimatedUsageUsd*1e6))/1e6 : null;
    report.push({json:{rowType:'take',project:plan.project,shotId:s.shotId,taskId:t.taskId,taskStatus:t.status,actualPreset:t.actualPreset??'',outputSeconds:t.outputSeconds??null,estimatedUsageUsd:t.estimatedUsageUsd??null,chargedUsd:t.chargedUsd??null,chargedMinusEstimateUsd:variance,note:t.note??''}});
  }
}
return report;
